<template><div class="container-page py-10"><div class="flex items-center justify-between"><div><p class="text-sm font-semibold text-primary-700">Admin</p><h1 class="text-3xl">SEO Blog</h1></div><NuxtLink to="/admin/blog/new" class="btn-primary">New Article</NuxtLink></div><div class="card mt-8 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-neutral-100"><tr><th class="p-4">Title</th><th class="p-4">Status</th><th class="p-4">Published</th></tr></thead><tbody><tr v-for="post in posts" :key="post.id" class="border-t"><td class="p-4 font-semibold">{{post.title}}</td><td class="p-4"><span :class="post.published?'badge-success':'badge-warning'">{{post.published?'Published':'Draft'}}</span></td><td class="p-4">{{post.published_at||'—'}}</td></tr></tbody></table></div></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin-auth'});const{data:posts}=useAsyncData('admin-blog',async()=>{const{data,error}=await useSupabase().from('blog_posts').select('*').order('created_at',{ascending:false});if(error)throw error;return data||[]});useSeoMeta({title:'SEO Blog | Admin',robots:'noindex,nofollow'})</script>
